export class ReportService {
  private db: Database;
  private cache: Cache;

  constructor(db: Database, cache: Cache) {
    this.db = db;
    this.cache = cache;
  }

  // Get all reports for a user
  async getUserReports(userId: string): Promise<Report[]> {
    // Check cache first
    const cached = await this.cache.get(`reports:${userId}`);
    if (cached) return JSON.parse(cached);
    // Fetch from database
    const reports = await this.db.query('SELECT * FROM reports WHERE user_id = $1', [userId]);
    // Store in cache
    await this.cache.set(`reports:${userId}`, JSON.stringify(reports), 300);
    return reports;
  }

